script:
(function () {
  'use strict';
  // 401(k) projection: each year you defer contrib% of pay and the employer matches match% of
  // your deferral up to matchCap% of pay; deposits go in monthly and compound monthly at
  // (1 + annual return)^(1/12) - 1. Optional caps: 402(g) deferral + catch-up, 415(c) total
  // additions and the 401(a)(17) pay limit. Checked in Node: $500/month at 7% for 30 years matches
  // the annuity formula ($584,726.30); $10,000 at 7% for 30 years = $76,122.55; $75,000 at 10% with
  // 50% match up to 6% = $7,500 + $2,250; caps of $24,500 (age 40), $32,500 (55), $35,750 (61);
  // 415(c) caps employer money at $72,000 - $24,500 = $47,500.
  // ---- 2026 IRS limits (IRS Notice 2025-67, tax year 2026) ----------------------
  var LIMITS = {
    year: 2026,
    deferral: 24500,        // 402(g) elective deferral limit (employee pre-tax + Roth)
    catchUp50: 8000,        // catch-up, age 50 or older by year-end
    catchUp60to63: 11250,   // SECURE 2.0 higher catch-up, ages 60-63 (replaces the age-50 amount)
    annualAdditions: 72000, // 415(c) limit on employee deferrals + employer money (catch-up excluded)
    compensation: 360000    // 401(a)(17) maximum pay that can be counted for the plan
  };
  // --------------------------------------------------------------------------------

  function catchUpFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }

  // p: age, retireAge, salary, raise, balance, contrib, match, matchCap, rate, inflation
  // (all rates as decimals), applyLimits (bool). Contributions are spread over 12 monthly
  // deposits; the balance compounds at the monthly rate equivalent to the annual return.
  function project(p) {
    var years = p.retireAge - p.age;
    var mRate = Math.pow(1 + p.rate, 1 / 12) - 1;
    var bal = p.balance, salary = p.salary, totYou = 0, totEr = 0, rows = [], capped = false;
    for (var y = 0; y < years; y++) {
      var ageNow = p.age + y;
      var pay = p.applyLimits ? Math.min(salary, LIMITS.compensation) : salary;
      var you = pay * p.contrib;
      if (p.applyLimits) {
        var maxYou = LIMITS.deferral + catchUpFor(ageNow);
        if (you > maxYou) { you = maxYou; capped = true; }
      }
      var effPct = pay > 0 ? you / pay : 0;
      var er = pay * p.match * Math.min(effPct, p.matchCap);
      if (p.applyLimits) {
        var regular = Math.min(you, LIMITS.deferral);
        if (regular + er > LIMITS.annualAdditions) { er = Math.max(0, LIMITS.annualAdditions - regular); capped = true; }
      }
      var dep = (you + er) / 12;
      for (var m = 0; m < 12; m++) bal = bal * (1 + mRate) + dep;
      totYou += you; totEr += er;
      rows.push({ year: y + 1, age: ageNow, salary: salary, you: you, er: er, balance: bal });
      salary = salary * (1 + p.raise);
    }
    var startPay = p.applyLimits ? Math.min(p.salary, LIMITS.compensation) : p.salary;
    var missed = p.contrib < p.matchCap ? startPay * p.match * (p.matchCap - p.contrib) : 0;
    return {
      balance: bal, real: bal / Math.pow(1 + p.inflation, years), you: totYou, er: totEr,
      growth: bal - p.balance - totYou - totEr, rows: rows, capped: capped, missed: missed, years: years
    };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); } };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var age = Math.round(num('fkAge')), retireAge = Math.round(num('fkRetireAge')), salary = num('fkSalary'),
        raise = num('fkRaise'), balance = num('fkBalance'), contrib = num('fkContrib'), match = num('fkMatch'),
        matchCap = num('fkMatchCap'), rate = num('fkRate'), inflation = num('fkInflation'),
        applyLimits = document.getElementById('fkLimits').checked;
    var error = document.getElementById('fkError');
    var bad = [age, retireAge, salary, raise, balance, contrib, match, matchCap, rate, inflation].some(isNaN) ||
              age < 16 || age > 99 || retireAge <= age || retireAge > 100 || salary < 0 || balance < 0 ||
              raise < 0 || raise > 20 || contrib < 0 || contrib > 100 || match < 0 || match > 200 ||
              matchCap < 0 || matchCap > 100 || rate < 0 || rate > 30 || inflation < 0 || inflation > 20;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an age from 16 to 99, a retirement age above it (up to 100), non-negative amounts, ' +
                          'percentages from 0 to 100 (match up to 200%), a return up to 30% and inflation up to 20%.';
      return;
    }
    var r = project({ age: age, retireAge: retireAge, salary: salary, raise: raise / 100, balance: balance,
                      contrib: contrib / 100, match: match / 100, matchCap: matchCap / 100, rate: rate / 100,
                      inflation: inflation / 100, applyLimits: applyLimits });
    set('fkFuture', money.format(r.balance));
    set('fkReal', money.format(r.real));
    set('fkYou', money.format(r.you));
    set('fkEr', money.format(r.er));
    set('fkGrowth', money.format(r.growth));
    set('fkRetireLabel', 'Balance at age ' + retireAge);
    var first = r.rows[0];
    set('fkFirstYear', 'First year: you put in ' + money.format(first.you) + ' and your employer adds ' +
        money.format(first.er) + ', a total of ' + money.format(first.you + first.er) + '.');
    var missedEl = document.getElementById('fkMissed');
    missedEl.hidden = !(r.missed > 0.5);
    if (r.missed > 0.5) {
      set('fkMissed', 'You are contributing less than the match limit. Raising your contribution to ' + matchCap +
          '% would add about ' + money.format(r.missed) + ' of employer money in the first year.');
    }
    var capEl = document.getElementById('fkCapped');
    capEl.hidden = !r.capped;
    if (r.capped) {
      set('fkCapped', 'In some years your contribution or your employer\'s is reduced to stay within the ' +
          LIMITS.year + ' IRS limits shown below.');
    }
    var body = document.getElementById('fkSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, money.format(row.salary), money.format(row.you), money.format(row.er), money.format(row.balance)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    set('fkLimitDeferral', money.format(LIMITS.deferral));
    set('fkLimitCatch50', money.format(LIMITS.catchUp50));
    set('fkLimitCatch60', money.format(LIMITS.catchUp60to63));
    set('fkLimitTotal', money.format(LIMITS.annualAdditions));
    var form = document.getElementById('fkForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
